import { NEXT_PUBLIC_WEBAPP_URL } from '@documenso/lib/constants/app';
import { prisma } from '@documenso/prisma';
import { type APIRequestContext, expect, test } from '@playwright/test';

import { apiSeedDraftDocument } from '../../fixtures/api-seeds';

const API_BASE_URL = `${NEXT_PUBLIC_WEBAPP_URL()}/api/v2-beta`;

/**
 * `Recipient.signingOrder` is an Int column, but nothing constrained the input
 * to an integer. Prisma does not reject a fraction — it truncates it (1.5 -> 1),
 * so distinct orders could silently collapse onto the same value, which under
 * signing groups means "same step". Negatives were persisted as-is and sort
 * ahead of everything, including the `?? 0` fallback in assistant scoping.
 * Zero remains valid for legacy handling.
 */

const createRecipient = async (request: APIRequestContext, token: string, envelopeId: string, signingOrder: number) =>
  await request.post(`${API_BASE_URL}/envelope/recipient/create-many`, {
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    data: {
      envelopeId,
      data: [
        {
          email: `signing-order-${Date.now()}-${signingOrder}@documenso.com`,
          name: 'Signing Order Test',
          role: 'SIGNER',
          signingOrder,
        },
      ],
    },
  });

test('[SIGNING_ORDER_VALIDATION]: rejects a fractional signing order with a client error', async ({ request }) => {
  const { envelope, token } = await apiSeedDraftDocument(request, { title: '[TEST] Signing order validation' });

  const response = await createRecipient(request, token, envelope.id, 1.5);

  expect(response.status()).toBe(400);

  // Nothing may be written — in particular not a silently truncated `1`.
  const recipients = await prisma.recipient.findMany({ where: { envelopeId: envelope.id } });

  expect(recipients).toHaveLength(0);
});

test('[SIGNING_ORDER_VALIDATION]: rejects a negative signing order', async ({ request }) => {
  const { envelope, token } = await apiSeedDraftDocument(request, {
    title: '[TEST] Signing order validation negative',
  });

  const response = await createRecipient(request, token, envelope.id, -1);

  expect(response.status()).toBe(400);

  const persisted = await prisma.recipient.findMany({ where: { envelopeId: envelope.id, signingOrder: -1 } });

  expect(persisted).toHaveLength(0);
});

test('[SIGNING_ORDER_VALIDATION]: still accepts a valid positive integer signing order', async ({ request }) => {
  const { envelope, token } = await apiSeedDraftDocument(request, { title: '[TEST] Signing order validation valid' });

  const response = await createRecipient(request, token, envelope.id, 2);

  expect(response.ok(), await response.text()).toBeTruthy();

  const persisted = await prisma.recipient.findMany({ where: { envelopeId: envelope.id, signingOrder: 2 } });

  expect(persisted).toHaveLength(1);
});

import { DOCUMENT_AUTH_TYPES } from '@documenso/lib/constants/document-auth';
import { RecipientActionAuth } from '@documenso/lib/types/document-auth';
import { MultiSelect, type Option } from '@documenso/ui/primitives/multiselect';
import { Tooltip, TooltipContent, TooltipTrigger } from '@documenso/ui/primitives/tooltip';
import { msg } from '@lingui/core/macro';
import { useLingui } from '@lingui/react';
import { Trans } from '@lingui/react/macro';
import { InfoIcon } from 'lucide-react';

import { cn } from '../../lib/utils';

export interface RecipientActionAuthSelectProps {
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  disabled?: boolean;
  placeholder?: string;
}

export const RecipientActionAuthSelect = ({
  value,
  defaultValue,
  onValueChange,
  disabled,
  placeholder,
}: RecipientActionAuthSelectProps) => {
  const { _ } = useLingui();

  // Convert auth types to MultiSelect options
  const authOptions: Option[] = [
    {
      value: '-1',
      label: _(msg`Inherit authentication method`),
    },
    ...Object.values(RecipientActionAuth)
      .filter((auth) => auth !== RecipientActionAuth.ACCOUNT)
      .map((authType) => ({
        value: authType,
        label: _(DOCUMENT_AUTH_TYPES[authType].value),
      })),
  ];

  // Convert string array to Option array for MultiSelect
  const selectedOptions =
    (value?.map((val) => authOptions.find((option) => option.value === val)).filter(Boolean) as Option[]) || [];

  // Convert default value to Option array
  const defaultOptions =
    (defaultValue?.map((val) => authOptions.find((option) => option.value === val)).filter(Boolean) as Option[]) || [];

  const handleChange = (options: Option[]) => {
    const values = options.map((option) => option.value);
    onValueChange?.(values);
  };

  return (
    <div className="relative">
      <MultiSelect
        value={selectedOptions}
        defaultOptions={defaultOptions}
        options={authOptions}
        onChange={handleChange}
        disabled={disabled}
        placeholder={placeholder || _(msg`Select authentication methods`)}
        className="bg-background text-muted-foreground"
        maxSelected={4} // Allow selecting up to 4 auth methods
        hideClearAllButton={false}
      />

      <Tooltip>
        <TooltipTrigger
          className={cn('absolute top-1/2 right-2 -translate-y-1/2', {
            'right-8': selectedOptions.length > 0,
          })}
        >
          <InfoIcon className="h-4 w-4" />
        </TooltipTrigger>

        <TooltipContent className="max-w-md p-4 text-foreground">
          <h2>
            <strong>
              <Trans>Recipient action authentication</Trans>
            </strong>
          </h2>

          <p>
            <Trans>The authentication methods required for recipients to sign fields</Trans>
          </p>

          <p className="mt-2">
            <Trans>These will override any global settings. Multiple methods can be selected.</Trans>
          </p>

          <ul className="ml-3.5 list-outside list-disc space-y-0.5 py-2">
            <li>
              <Trans>
                <strong>Inherit authentication method</strong> - Use the global action signing authentication method
                configured in the "General Settings" step
              </Trans>
            </li>
            <li>
              <Trans>
                <strong>Require passkey</strong> - The recipient must have an account and passkey configured via their
                settings
              </Trans>
            </li>
            <li>
              <Trans>
                <strong>Require 2FA</strong> - The recipient must have an account and 2FA enabled via their settings
              </Trans>
            </li>
            <li>
              <Trans>
                <strong>None</strong> - No authentication required
              </Trans>
            </li>
          </ul>
        </TooltipContent>
      </Tooltip>
    </div>
  );
};

import { createDocumentAuthOptions } from '@documenso/lib/utils/document-auth';
import { prisma } from '@documenso/prisma';
import { seedPendingDocumentWithFullFields } from '@documenso/prisma/seed/documents';
import { seedUser } from '@documenso/prisma/seed/users';
import { expect, test } from '@playwright/test';
import { FieldType } from '@prisma/client';

import { apiSignin } from '../fixtures/authentication';
import { waitForHydration } from '../fixtures/hydration';
import { signSignaturePad } from '../fixtures/signature';

test.describe.configure({ mode: 'parallel', timeout: 60000 });

const SEEDED_PASSWORD = 'password';
const NEW_PASSWORD = 'Test123!';

/**
 * Seed a document requiring PASSWORD action auth for a recipient with an account,
 * and sign the recipient in on the signing page.
 *
 * Action auth is gated behind the cfr21 claim flag at write time only, so seeding
 * the auth options directly bypasses the gate the same way action-auth.spec.ts does.
 */
const seedPasswordActionAuthDocument = async () => {
  const { user: owner, team } = await seedUser();
  const { user: recipient } = await seedUser();

  const { recipients } = await seedPendingDocumentWithFullFields({
    owner,
    teamId: team.id,
    recipients: [recipient],
    updateDocumentOptions: {
      authOptions: createDocumentAuthOptions({
        globalAccessAuth: [],
        globalActionAuth: ['PASSWORD'],
      }),
    },
    fields: [FieldType.SIGNATURE],
  });

  const { token, fields } = recipients[0];

  const signatureField = fields.find((field) => field.type === FieldType.SIGNATURE);

  if (!signatureField) {
    throw new Error('Expected a signature field to be seeded');
  }

  return {
    recipient,
    signUrl: `/sign/${token}`,
    signatureField,
  };
};

test('[DOCUMENT_AUTH]: passwordless user is sent a setup link and can sign after setting a password', async ({
  page,
}) => {
  const { recipient, signUrl, signatureField } = await seedPasswordActionAuthDocument();

  await apiSignin({
    page,
    email: recipient.email,
    password: SEEDED_PASSWORD,
    redirectPath: signUrl,
  });

  // Simulate an OAuth / passkey only account by removing the password after sign in.
  await prisma.user.update({
    where: { id: recipient.id },
    data: { password: null },
  });

  await expect(page.getByRole('heading', { name: 'Sign Document' })).toBeVisible();

  await signSignaturePad(page);

  await page.locator(`#field-${signatureField.id}`).getByRole('button').click();

  await expect(page.getByText('Reauthentication is required to sign this field')).toBeVisible();
  await expect(page.getByText('No password set')).toBeVisible();

  // A bare session must not be able to set a password inline; it gets emailed a link instead.
  await expect(page.getByLabel('New password')).not.toBeVisible();

  await page.getByRole('button', { name: 'Send setup link' }).click();
  await expect(page.getByText('Check your email')).toBeVisible();

  const resetToken = await prisma.passwordResetToken.findFirstOrThrow({
    where: { userId: recipient.id },
  });

  // Complete the emailed flow, which also invalidates all sessions.
  await page.goto(`/reset-password/${resetToken.token}`);

  // Filling controlled inputs before hydration gets reset by React.
  await waitForHydration(page, 'input[name="password"]');

  await page.getByLabel('Password', { exact: true }).fill(NEW_PASSWORD);
  await page.getByLabel('Repeat Password').fill(NEW_PASSWORD);
  await page.getByRole('button', { name: 'Reset Password' }).click();
  await expect(page.locator('body')).toContainText('Your password has been updated successfully.');

  // Come back with the new password and the normal reauth form should now work.
  await apiSignin({
    page,
    email: recipient.email,
    password: NEW_PASSWORD,
    redirectPath: signUrl,
  });

  await expect(page.getByRole('heading', { name: 'Sign Document' })).toBeVisible();

  await signSignaturePad(page);

  await page.locator(`#field-${signatureField.id}`).getByRole('button').click();

  const dialog = page.getByRole('dialog');

  await expect(dialog.getByText('No password set')).not.toBeVisible();

  await dialog.getByLabel('Password').fill(NEW_PASSWORD);
  await dialog.getByRole('button', { name: 'Sign' }).click();

  await expect(page.locator(`#field-${signatureField.id}`)).toHaveAttribute('data-inserted', 'true');
});

test('[DOCUMENT_AUTH]: user with a password sees the normal password reauth form', async ({ page }) => {
  const { recipient, signUrl, signatureField } = await seedPasswordActionAuthDocument();

  await apiSignin({
    page,
    email: recipient.email,
    password: SEEDED_PASSWORD,
    redirectPath: signUrl,
  });

  await expect(page.getByRole('heading', { name: 'Sign Document' })).toBeVisible();

  await signSignaturePad(page);

  await page.locator(`#field-${signatureField.id}`).getByRole('button').click();

  await expect(page.getByText('Reauthentication is required to sign this field')).toBeVisible();
  await expect(page.getByText('No password set')).not.toBeVisible();

  const dialog = page.getByRole('dialog');

  // Wrong password is rejected.
  await dialog.getByLabel('Password').fill('wrong-password');
  await dialog.getByRole('button', { name: 'Sign' }).click();
  await expect(dialog.getByText('Unauthorized')).toBeVisible();

  // Correct password signs the field.
  await dialog.getByLabel('Password').fill(SEEDED_PASSWORD);
  await dialog.getByRole('button', { name: 'Sign' }).click();

  await expect(page.locator(`#field-${signatureField.id}`)).toHaveAttribute('data-inserted', 'true');
});

test('[DOCUMENT_AUTH]: passwordless user can request a setup link from security settings', async ({ page }) => {
  const { user } = await seedUser();

  await apiSignin({
    page,
    email: user.email,
    password: SEEDED_PASSWORD,
    redirectPath: '/settings/profile',
  });

  await prisma.user.update({
    where: { id: user.id },
    data: { password: null },
  });

  await page.goto('/settings/security');

  await expect(page.getByRole('heading', { name: 'Set a password' })).toBeVisible();
  await expect(page.getByLabel('Current password')).not.toBeVisible();
  await expect(page.getByLabel('New password')).not.toBeVisible();

  // Clicking before hydration is a no-op, so retry until the sent state appears.
  await expect(async () => {
    await page.getByRole('button', { name: 'Send setup link' }).click();
    await expect(page.getByRole('button', { name: 'Link sent' })).toBeVisible({ timeout: 2_000 });
  }).toPass({ timeout: 15_000 });

  const resetToken = await prisma.passwordResetToken.findFirst({
    where: { userId: user.id },
  });

  expect(resetToken).not.toBeNull();
});

import { ZRecipientAuthOptionsSchema } from '@documenso/lib/types/document-auth';
import { createDocumentAuthOptions, createRecipientAuthOptions } from '@documenso/lib/utils/document-auth';
import { seedPendingDocumentNoFields, seedPendingDocumentWithFullFields } from '@documenso/prisma/seed/documents';
import { seedTestEmail, seedUser } from '@documenso/prisma/seed/users';
import { expect, test } from '@playwright/test';
import { FieldType } from '@prisma/client';

import { apiSignin, apiSignout } from '../fixtures/authentication';
import { signSignaturePad } from '../fixtures/signature';

test.describe.configure({ mode: 'parallel', timeout: 60000 });

test('[DOCUMENT_AUTH]: should allow signing when no auth setup', async ({ page }) => {
  const { user, team } = await seedUser();

  const { user: recipientWithAccount } = await seedUser();

  const { recipients } = await seedPendingDocumentWithFullFields({
    owner: user,
    teamId: team.id,
    recipients: [recipientWithAccount, seedTestEmail()],
  });

  // Check that both are granted access.
  for (const recipient of recipients) {
    const { token, fields } = recipient;

    const signUrl = `/sign/${token}`;

    await page.goto(signUrl);
    await expect(page.getByRole('heading', { name: 'Sign Document' })).toBeVisible();

    await signSignaturePad(page);

    for (const field of fields) {
      await page.locator(`#field-${field.id}`).getByRole('button').click();

      if (field.type === FieldType.TEXT) {
        await page.locator('#custom-text').fill('TEXT');
        await page.getByRole('button', { name: 'Save' }).click();
      }

      await expect(page.locator(`#field-${field.id}`)).toHaveAttribute('data-inserted', 'true');
    }

    await page.getByRole('button', { name: 'Complete' }).click();
    await page.getByRole('button', { name: 'Sign' }).click();
    await page.waitForURL(`${signUrl}/complete`);
  }
});

