test('[ADMIN][TRPC][DELETE_RECIPIENT]: sequential signing advances to the next recipient', async ({ page }) => {
  const { user: adminUser } = await seedUser({ isAdmin: true });
  const { user: owner, team } = await seedUser();

  const document = await seedPendingDocument(owner, team.id, [
    'first@test.documenso.com',
    'second@test.documenso.com',
    'third@test.documenso.com',
  ]);

  await prisma.documentMeta.update({
    where: { id: document.documentMetaId },
    data: { signingOrder: DocumentSigningOrder.SEQUENTIAL },
  });

  const [first, second, third] = ['first', 'second', 'third'].map((prefix) => {
    const recipient = document.recipients.find((r) => r.email === `${prefix}@test.documenso.com`);

    if (!recipient) {
      throw new Error(`Recipient ${prefix} not seeded`);
    }

    return recipient;
  });

  await prisma.recipient.update({
    where: { id: first.id },
    data: { signingOrder: 1, sendStatus: SendStatus.SENT },
  });

  await prisma.recipient.update({
    where: { id: second.id },
    data: { signingOrder: 2, sendStatus: SendStatus.NOT_SENT, sentAt: null },
  });

  await prisma.recipient.update({
    where: { id: third.id },
    data: { signingOrder: 3, sendStatus: SendStatus.NOT_SENT, sentAt: null },
  });

  await apiSignin({ page, email: adminUser.email });

  const res = await callDeleteRecipient(page, { id: first.id });

  expect(res.ok()).toBeTruthy();

  const updatedSecond = await prisma.recipient.findUniqueOrThrow({ where: { id: second.id } });
  expect(updatedSecond.sendStatus).toBe(SendStatus.SENT);

  const updatedThird = await prisma.recipient.findUniqueOrThrow({ where: { id: third.id } });
  expect(updatedThird.sendStatus).toBe(SendStatus.NOT_SENT);

  const signingJob = await prisma.backgroundJob.findFirst({
    where: {
      jobId: 'send.signing.requested.email',
      AND: [
        { payload: { path: ['documentId'], equals: mapSecondaryIdToDocumentId(document.secondaryId) } },
        { payload: { path: ['recipientId'], equals: second.id } },
      ],
    },
  });

  expect(signingJob).not.toBeNull();

  const thirdSigningJob = await prisma.backgroundJob.findFirst({
    where: {
      jobId: 'send.signing.requested.email',
      AND: [
        { payload: { path: ['documentId'], equals: mapSecondaryIdToDocumentId(document.secondaryId) } },
        { payload: { path: ['recipientId'], equals: third.id } },
      ],
    },
  });

  expect(thirdSigningJob).toBeNull();

  expect(
    await findJobByDocumentId('internal.seal-document', mapSecondaryIdToDocumentId(document.secondaryId)),
  ).toBeNull();
});

import { NEXT_PUBLIC_WEBAPP_URL } from '@documenso/lib/constants/app';
import { createApiToken } from '@documenso/lib/server-only/public-api/create-api-token';
import { mapSecondaryIdToDocumentId } from '@documenso/lib/utils/envelope';
import { prisma } from '@documenso/prisma';
import { SendStatus, SigningStatus } from '@documenso/prisma/client';
import { seedPendingDocument } from '@documenso/prisma/seed/documents';
import { seedUser } from '@documenso/prisma/seed/users';
import { expect, test } from '@playwright/test';
import type { Team, User } from '@prisma/client';

const WEBAPP_BASE_URL = NEXT_PUBLIC_WEBAPP_URL();
const baseUrl = `${WEBAPP_BASE_URL}/api/v2-beta`;

test.describe.configure({
  mode: 'parallel',
});

test.describe('Redistribute updates recipient send status', () => {
  let user: User, team: Team, token: string;

  test.beforeEach(async () => {
    ({ user, team } = await seedUser());
    ({ token } = await createApiToken({
      userId: user.id,
      teamId: team.id,
      tokenName: 'test',
      expiresIn: null,
    }));
  });

  test('marks a NOT_SENT signer as SENT after a successful resend', async ({ request }) => {
    const document = await seedPendingDocument(user, team.id, ['recipient@test.documenso.com']);

    const [recipient] = document.recipients;

    // Simulate a recipient that is stuck at NOT_SENT on a pending document
    // (e.g. the initial send did not dispatch an email for them).
    await prisma.recipient.update({
      where: { id: recipient.id },
      data: {
        sendStatus: SendStatus.NOT_SENT,
        signingStatus: SigningStatus.NOT_SIGNED,
        sentAt: null,
      },
    });

    const res = await request.post(`${baseUrl}/document/redistribute`, {
      headers: { Authorization: `Bearer ${token}` },
      data: {
        documentId: mapSecondaryIdToDocumentId(document.secondaryId),
        recipients: [recipient.id],
      },
    });

    expect(res.ok(), `redistribute should succeed: ${await res.text()}`).toBeTruthy();

    const updatedRecipient = await prisma.recipient.findFirstOrThrow({
      where: { id: recipient.id },
    });

    expect(updatedRecipient.sendStatus).toBe(SendStatus.SENT);
    expect(updatedRecipient.sentAt).not.toBeNull();
  });
});

import fs from 'node:fs';
import path from 'node:path';
import { NEXT_PUBLIC_WEBAPP_URL } from '@documenso/lib/constants/app';
import { createApiToken } from '@documenso/lib/server-only/public-api/create-api-token';
import { EnvelopeType, FieldType, RecipientRole } from '@documenso/prisma/client';
import { seedUser } from '@documenso/prisma/seed/users';
import type {
  TCreateEnvelopePayload,
  TCreateEnvelopeResponse,
} from '@documenso/trpc/server/envelope-router/create-envelope.types';
import type { TCreateEnvelopeRecipientsRequest } from '@documenso/trpc/server/envelope-router/envelope-recipients/create-envelope-recipients.types';
import type { TGetEnvelopeResponse } from '@documenso/trpc/server/envelope-router/get-envelope.types';
import { type APIRequestContext, expect, test } from '@playwright/test';
import type { Team, User } from '@prisma/client';

const WEBAPP_BASE_URL = NEXT_PUBLIC_WEBAPP_URL();
const baseUrl = `${WEBAPP_BASE_URL}/api/v2-beta`;

test.describe.configure({
  mode: 'parallel',
});

test.describe('Envelope distribute validation', () => {
  let user: User, team: Team, token: string;

  test.beforeEach(async () => {
    ({ user, team } = await seedUser());
    ({ token } = await createApiToken({
      userId: user.id,
      teamId: team.id,
      tokenName: 'test',
      expiresIn: null,
    }));
  });

  const createEnvelope = async (request: APIRequestContext, authToken: string) => {
    const payload: TCreateEnvelopePayload = {
      type: EnvelopeType.DOCUMENT,
      title: 'Test Document',
    };

    const formData = new FormData();
    formData.append('payload', JSON.stringify(payload));

    const pdfData = fs.readFileSync(path.join(__dirname, '../../../../../assets/example.pdf'));
    formData.append('files', new File([pdfData], 'test.pdf', { type: 'application/pdf' }));

    const res = await request.post(`${baseUrl}/envelope/create`, {
      headers: { Authorization: `Bearer ${authToken}` },
      multipart: formData,
    });

    expect(res.ok()).toBeTruthy();
    return (await res.json()) as TCreateEnvelopeResponse;
  };

  const getEnvelope = async (request: APIRequestContext, authToken: string, envelopeId: string) => {
    const res = await request.get(`${baseUrl}/envelope/${envelopeId}`, {
      headers: { Authorization: `Bearer ${authToken}` },
    });

    expect(res.ok()).toBeTruthy();
    return (await res.json()) as TGetEnvelopeResponse;
  };

  const createRecipients = async (
    request: APIRequestContext,
    authToken: string,
    envelopeId: string,
    recipients: TCreateEnvelopeRecipientsRequest['data'],
  ) => {
    const res = await request.post(`${baseUrl}/envelope/recipient/create-many`, {
      headers: { Authorization: `Bearer ${authToken}` },
      data: {
        envelopeId,
        data: recipients,
      } satisfies TCreateEnvelopeRecipientsRequest,
    });

    expect(res.ok()).toBeTruthy();
    return (await res.json()).data;
  };

  const createFields = async (
    request: APIRequestContext,
    authToken: string,
    envelopeId: string,
    envelopeItemId: string,
    fields: Array<{ recipientId: number; type: FieldType }>,
  ) => {
    const res = await request.post(`${baseUrl}/envelope/field/create-many`, {
      headers: { Authorization: `Bearer ${authToken}` },
      data: {
        envelopeId,
        data: fields.map((field, index) => ({
          recipientId: field.recipientId,
          envelopeItemId,
          type: field.type,
          page: 1,
          positionX: 10,
          positionY: 10 + index * 10,
          width: 10,
          height: 10,
        })),
      },
    });

    expect(res.ok()).toBeTruthy();
    return (await res.json()).data;
  };

  test('should fail to distribute when signer has no fields', async ({ request }) => {
    const envelope = await createEnvelope(request, token);

    // Create a signer without any fields
    await createRecipients(request, token, envelope.id, [
      {
        email: 'signer@example.com',
        name: 'Test Signer',
        role: RecipientRole.SIGNER,
        accessAuth: [],
        actionAuth: [],
      },
    ]);

    // Try to distribute without adding any fields
    const distributeRes = await request.post(`${baseUrl}/envelope/distribute`, {
      headers: { Authorization: `Bearer ${token}` },
      data: { envelopeId: envelope.id },
    });

    expect(distributeRes.ok()).toBeFalsy();
    expect(distributeRes.status()).toBe(400);

    const errorResponse = await distributeRes.json();
    expect(errorResponse.message).toContain('missing required fields');
    expect(errorResponse.message).toContain('Signers must have at least one signature field');
